import json

with open('/home/ubuntu/.claude-account-2/projects/-home-ubuntu--agent-ml-research-idea-gen-0513-2-projects-recursive-gen-depth-est/aa4971ca-a587-40fb-928d-429940857a96/tool-results/mcp-agent-ml-research-read_registry-1778908883855.txt') as f:
    data = json.load(f)

result_str = data['result']
result = json.loads(result_str)

if isinstance(result, dict) and 'data' in result:
    d = result['data']
    if isinstance(d, dict):
        exps = d.get('experiments', d)
        if isinstance(exps, dict):
            # dict of exp_id -> exp_data
            for exp_id, exp_data in list(exps.items())[:2]:
                print(f'exp_id: {exp_id}')
                print(f'type: {type(exp_data)}')
                if isinstance(exp_data, dict):
                    print(json.dumps(exp_data, indent=2, default=str)[:1000])
                else:
                    print(str(exp_data)[:500])
                print()
        elif isinstance(exps, list):
            for item in exps[:2]:
                print(f'type: {type(item)}')
                print(str(item)[:500])
                print()
    else:
        print(f'data type: {type(d)}')
        print(str(d)[:1000])
else:
    print(f'result type: {type(result)}')
    if isinstance(result, dict):
        print('keys:', list(result.keys()))
    print(str(result)[:1000])
